<template><ion-page><ion-header><ion-toolbar><ion-buttons slot="start"><ion-menu-button/></ion-buttons><ion-title>SpiderFoot API</ion-title></ion-toolbar></ion-header><ion-content class="ion-padding">
<ion-card><ion-card-header><ion-card-title>Endpoint explorer</ion-card-title><ion-card-subtitle>Validated SpiderFoot operations exposed by Sherlock</ion-card-subtitle></ion-card-header><ion-card-content><ion-searchbar v-model="query" placeholder="Filter endpoints"/><ion-select v-model="selectedName" label="Endpoint" label-placement="stacked" fill="outline"><ion-select-option v-for="name in filtered" :key="name" :value="name">{{catalog[name].method}} {{name}}</ion-select-option></ion-select><div v-if="selected"><ion-note v-if="selected.mutating" color="warning">This changes SpiderFoot state.</ion-note><ion-input v-for="name in selected.parameters" :key="name" v-model="params[name]" :label="name" label-placement="stacked" fill="outline" class="ion-margin-top"/><ion-button expand="block" class="ion-margin-top" :color="selected.mutating?'warning':'primary'" :disabled="working" @click="run">Run endpoint</ion-button></div></ion-card-content></ion-card>
<ion-card v-if="error"><ion-card-content class="error">{{error}}</ion-card-content></ion-card><ion-card v-if="result!==null"><ion-card-header><ion-card-title>Response</ion-card-title></ion-card-header><ion-card-content><pre>{{JSON.stringify(result,null,2)}}</pre></ion-card-content></ion-card>
</ion-content></ion-page></template>
<script setup lang="ts">import{computed,onMounted,ref,watch}from'vue';import{SpiderFootService,type SpiderFootEndpoint}from'@/services/SpiderFootService';const catalog=ref<Record<string,SpiderFootEndpoint>>({}),query=ref(''),selectedName=ref(''),params=ref<Record<string,string>>({}),result=ref<unknown|null>(null),error=ref(''),working=ref(false);const filtered=computed(()=>Object.keys(catalog.value).filter(n=>n.toLowerCase().includes(query.value.toLowerCase())));const selected=computed(()=>catalog.value[selectedName.value]);watch(selectedName,()=>{params.value=Object.fromEntries((selected.value?.parameters??[]).map(n=>[n,'']));result.value=null});const run=async()=>{if(selected.value?.mutating&&!window.confirm(`Run ${selectedName.value}? This changes SpiderFoot state.`))return;working.value=true;error.value='';try{result.value=await SpiderFootService.invoke(selectedName.value,selected.value,Object.fromEntries(Object.entries(params.value).filter(([,v])=>v!=='')))}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{working.value=false}};onMounted(async()=>{catalog.value=await SpiderFootService.catalog();selectedName.value=Object.keys(catalog.value)[0]??''});</script>
<style scoped>pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.error{color:var(--ion-color-danger)}</style>
